package org.solaris.receiver;
import android.app.*;import android.content.*;import android.media.projection.MediaProjectionManager;import android.net.Uri;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import androidx.webkit.WebViewAssetLoader;import org.json.*;import java.util.concurrent.*;

public final class SolarisActivity extends Activity{
 private static final String ORIGIN="https://appassets.androidplatform.net/assets/";
 private WebView web;private ScreenEngine screen;private DiskBridge disk;private final ExecutorService io=Executors.newSingleThreadExecutor();
 private String projectionRequest,pickerRequest,pickerCommand;private JSONObject projectionArgs,pickerArgs;private View custom;private WebChromeClient.CustomViewCallback customCallback;private ValueCallback<Uri[]> photoCallback;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);disk=new DiskBridge(this);screen=new ScreenEngine(this,disk,this::emit);web=new WebView(this);web.setBackgroundColor(0xff0d1016);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);WebViewAssetLoader loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build();
  web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return loader.shouldInterceptRequest(r.getUrl());}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith(ORIGIN);}});
  web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest r){r.deny();}@Override public void onShowCustomView(View v,CustomViewCallback cb){if(custom!=null){cb.onCustomViewHidden();return;}custom=v;customCallback=cb;setContentView(v);fullscreen(true);}@Override public void onHideCustomView(){if(custom==null)return;custom=null;setContentView(web);fullscreen(false);customCallback.onCustomViewHidden();customCallback=null;}@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){photoCallback=cb;startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE),45);return true;}});
  web.addJavascriptInterface(new JavascriptAPI(),"SolarisNative");setContentView(web);web.loadUrl(ORIGIN+"index.html");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},10);
 }
 public final class JavascriptAPI{@JavascriptInterface public void postMessage(String json){try{JSONObject m=new JSONObject(json);runOnUiThread(()->command(m));}catch(JSONException ignored){}}}
 private void fullscreen(boolean enabled){if(enabled)getWindow().getInsetsController().hide(WindowInsets.Type.systemBars());else getWindow().getInsetsController().show(WindowInsets.Type.systemBars());}
 void emit(JSONObject value){runOnUiThread(()->{if(value.optString("type").equals("media-ended"))stopService(new Intent(this,ProjectionService.class));if(web!=null)web.evaluateJavascript("window.dispatchEvent(new CustomEvent('solaris-native',{detail:"+value+"}))",null);});}
 private void reply(String id,Object value,Exception e){try{JSONObject r=new JSONObject().put("requestId",id);if(e!=null)r.put("error",e.getMessage());else r.put("result",value==null?JSONObject.NULL:value);emit(r);}catch(JSONException ignored){}}
 private void command(JSONObject m){String id=m.optString("requestId"),cmd=m.optString("command");JSONObject a=m.optJSONObject("args");final JSONObject args=a==null?new JSONObject():a;try{if(!m.optString("type").equals("solaris-command")||web==null||!ORIGIN.concat("index.html").equals(web.getUrl()))return;
  if(cmd.equals("platform")){reply(id,new JSONObject().put("platform","android").put("nativeSignaling",true).put("version","0.4.0-build56"),null);return;}
  if(cmd.equals("mediaStatus")){screen.status(value->reply(id,value,null));return;}
  if(cmd.equals("mediaStart")){if(projectionRequest!=null)throw new Exception("화면공유 시작이 진행 중입니다.");projectionRequest=id;projectionArgs=args;screen.stop();startActivityForResult(((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).createScreenCaptureIntent(),42);return;}
  if(cmd.equals("mediaStop")){screen.stop();stopService(new Intent(this,ProjectionService.class));reply(id,true,null);return;}if(cmd.startsWith("media")){screen.command(cmd,args);reply(id,true,null);return;}
  if(cmd.equals("fullscreen")){fullscreen(args.optBoolean("enabled"));reply(id,true,null);return;}
  if(cmd.equals("pickFile")||cmd.equals("createReceiver")){if(pickerRequest!=null)throw new Exception("파일 선택이 진행 중입니다.");pickerRequest=id;pickerCommand=cmd;pickerArgs=args;Intent in=new Intent(cmd.equals("pickFile")?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_CREATE_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);if(cmd.equals("createReceiver"))in.putExtra(Intent.EXTRA_TITLE,DiskBridge.safeName(args.getString("name")));startActivityForResult(in,43);return;}
  if(cmd.equals("openExternal")){String url=args.getString("url");if(!url.startsWith("https://github.com/m10180729-afk/solaris-ios-probe/releases/"))throw new Exception("Invalid update URL");startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));reply(id,true,null);return;}
  if(cmd.equals("notify")){NotificationManager manager=getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("solaris-transfers","Solaris 파일 전송",NotificationManager.IMPORTANCE_DEFAULT));if(Build.VERSION.SDK_INT<33||checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==android.content.pm.PackageManager.PERMISSION_GRANTED){PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,SolarisActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);manager.notify((args.optString("title")+args.optString("body")).hashCode(),new Notification.Builder(this,"solaris-transfers").setSmallIcon(android.R.drawable.ic_menu_share).setContentTitle(args.optString("title")).setContentText(args.optString("body")).setContentIntent(open).setAutoCancel(true).build());}reply(id,true,null);return;}if(cmd.equals("exportLog")){startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,args.getString("text")),"진단 내보내기"));reply(id,true,null);return;}if(cmd.equals("exportFile")){disk.exportFile(args.getString("id"));reply(id,true,null);return;}
  io.execute(()->{try{reply(id,disk.command(cmd,args),null);}catch(Exception e){reply(id,null,e);}});
 }catch(Exception e){reply(id,null,e);}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==42){String id=projectionRequest;projectionRequest=null;if(result!=RESULT_OK||data==null){reply(id,null,new Exception("화면공유가 취소되었습니다."));return;}ProjectionService.startCallback=()->{try{screen.start(data,projectionArgs,error->{if(error!=null)stopService(new Intent(this,ProjectionService.class));reply(id,error==null?true:null,error);});}catch(Exception e){reply(id,null,e);}};startForegroundService(new Intent(this,ProjectionService.class));}
 if(request==43){String id=pickerRequest,cmd=pickerCommand;JSONObject a=pickerArgs;pickerRequest=null;if(result!=RESULT_OK||data==null){reply(id,null,cmd.equals("pickFile")?null:new Exception("수신 취소"));return;}Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(SecurityException ignored){}io.execute(()->{try{reply(id,cmd.equals("pickFile")?disk.source(uri):disk.receiver(uri,a),null);}catch(Exception e){reply(id,null,e);}});}
 if(request==45&&photoCallback!=null){photoCallback.onReceiveValue(result==RESULT_OK&&data!=null?new Uri[]{data.getData()}:null);photoCallback=null;}}
 @Override public void onBackPressed(){if(custom!=null){custom=null;setContentView(web);fullscreen(false);if(customCallback!=null)customCallback.onCustomViewHidden();return;}super.onBackPressed();}
 private void lifecycle(String state){try{emit(new JSONObject().put("type","lifecycle").put("state",state));}catch(JSONException ignored){}}
 @Override protected void onStart(){super.onStart();lifecycle("foreground");}
 @Override protected void onStop(){lifecycle("background");super.onStop();}
 @Override protected void onDestroy(){screen.close();stopService(new Intent(this,ProjectionService.class));io.shutdown();if(web!=null){web.destroy();web=null;}super.onDestroy();}
}
